import java.io.*;
import java.util.*;

public class E {
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }

    static FastReader s = new FastReader();
    static PrintWriter out = new PrintWriter(System.out);

    private static int[] readIntArray(int n) {
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = s.nextInt();
        }
        return arr;
    }

    private static int[][] readIntMatrix(int n, int m) {
        int[][] arr = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                arr[i][j] = s.nextInt();
            }
        }
        return arr;
    }

    private static long[] readLongArray(int n) {
        long[] arr = new long[n];
        for (int i = 0; i < n; i++) {
            arr[i] = s.nextLong();
        }
        return arr;
    }

    private static long[][] readLongMatrix(int n, int m) {
        long[][] arr = new long[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                arr[i][j] = s.nextLong();
            }
        }
        return arr;
    }

    private static int getNextInt() {
        return s.nextInt();
    }

    private static long getNextLong() {
        return s.nextLong();
    }

    private static String getNextString() {
        return s.next();
    }

    static int gcd(int a, int b) {
        if (b == 0) {
            return a;
        }
        return gcd(b, a % b);
    }

    static int binarySearch(List<Long> list, long val, int startIndex) {
        int left = startIndex, right = list.size() - 1;
        int result = list.size();

        while (left <= right) {
            int mid = (left + right) / 2;
            if (list.get(mid) > val) {
                if (mid == 0) {
                    return mid;
                }
                if (list.get(mid - 1) <= val) {
                    return mid;
                }
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return result;
    }

    static long compute(List<Node> list, long[] b, int index) {
        if (index == 3) {
            return 0;
        }

        Node current = list.get(index);
        int bIndex = current.ind - 1;
        if (bIndex == -1) bIndex = 2;

        long min1 = Math.min(current.val, b[bIndex]);
        current.val -= min1;
        b[bIndex] -= min1;

        long min2 = Math.min(current.val, b[current.ind]);
        current.val -= min2;
        b[current.ind] -= min2;

        long total1 = current.val + compute(list, b, index + 1);
        current.val += min1 + min2;
        b[bIndex] += min1;
        b[current.ind] += min2;

        // Second scenario
        current = list.get(index);
        bIndex = current.ind - 1;
        if (bIndex == -1) bIndex = 2;

        long min3 = Math.min(current.val, b[current.ind]);
        current.val -= min3;
        b[current.ind] -= min3;

        long min4 = Math.min(current.val, b[bIndex]);
        current.val -= min4;
        b[bIndex] -= min4;

        long total2 = current.val + compute(list, b, index + 1);
        current.val += min3 + min4;
        b[bIndex] += min4;
        b[current.ind] += min3;

        return Math.min(total1, total2);
    }

    public static void main(String[] args) {
        StringBuilder answer = new StringBuilder();
        int t = 1; // fixed to 1 as in original
        while (t-- > 0) {
            int n = getNextInt();
            long[] a = readLongArray(3);
            long[] b = readLongArray(3);

            long maxVal = Math.min(a[0], b[1]) + Math.min(a[1], b[2]) + Math.min(a[2], b[0]);
            long minVal = Math.max(0, a[0] + b[1] - n) + Math.max(0, a[1] + b[2] - n) + Math.max(0, a[2] + b[0] - n);
            answer.append(minVal).append(" ").append(maxVal).append("\n");
        }
        out.print(answer.toString());
        out.flush();
    }

    static class Node {
        int ind;
        long val;

        public Node(int ind, long val) {
            this.ind = ind;
            this.val = val;
        }
    }
}
